import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ selectedCategories, onNext }) {

  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSave = () => {

    if (Object.keys(limits).length === 0) {
      alert("Please enter at least one budget");
      return;
    }

    onNext(limits);
  };

  return (
    <div className="budget-container">
      <h2 className="budget-title">Set Monthly Budget Limits</h2>

      <div className="budget-grid">

        {/* 🔥 DYNAMIC CATEGORIES */}
        {selectedCategories.map(cat => (
          <div className="budget-card" key={cat}>
            <h3>{cat}</h3>
            <input
              type="number"
              className="budget-input"
              placeholder="Enter amount"
              value={limits[cat] || ""}
              onChange={(e) =>
                handleChange(cat, e.target.value)
              }
            />
          </div>
        ))}

      </div>

      {/* 🔥 IMPROVED BUTTON */}
      <button
        className="budget-button"
        onClick={handleSave}
        style={{
          marginTop: "40px",
          width: "40%",
          padding: "15px",
          borderRadius: "14px",
          border: "none",
          fontSize: "16px",
          fontWeight: "600",
          background: "linear-gradient(135deg, #1e3c72, #2a5298)",
          color: "#ffffff",
          cursor: "pointer",
          display: "block",
          marginLeft: "auto",
          marginRight: "auto",
          transition: "all 0.3s ease"
        }}
      >
        Save Limits
      </button>
    </div>
  );
}

export default BudgetLimits;
